import '../index/index_operations.dart';

/// Generates a static Markdown snapshot for a data view (`T-02`).
String renderDataViewSnapshotMarkdown({
  required String title,
  required List<IndexedEntryWithDocument> entries,
  required DateTime generatedAt,
}) {
  final buf = StringBuffer();
  final isoTs = generatedAt.toUtc().toIso8601String();
  buf.writeln('# $title');
  buf.writeln();
  buf.writeln(
    '> Static snapshot generated by Citrine at $isoTs. '
    'This file will not auto-update when Citrine data changes.',
  );
  buf.writeln();

  if (entries.isEmpty) {
    buf.writeln('_No items in this view at snapshot time._');
    return buf.toString();
  }

  for (final item in entries) {
    final prefix = switch (item.entry.kind) {
      'task' => item.isCompletedTask ? '- [x] ' : '- [ ] ',
      'event' => '- ○ ',
      'note' => '- – ',
      _ => '- ',
    };
    buf.writeln('$prefix${item.entry.textContent}');
  }
  return buf.toString();
}
